const SUP={'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9'};
const state={chapter:+localStorage.getItem('dtb:chapter')||1,layer:'dima',data:null,saved:JSON.parse(localStorage.getItem('dtb:saved')||'[]'),read:JSON.parse(localStorage.getItem('dtb:read')||'[]'),opened:JSON.parse(localStorage.getItem('dtb:opened')||'[]'),font:+localStorage.getItem('dtb:font')||1,steps:JSON.parse(localStorage.getItem('dtb:steps')||'[]')};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let verseObserver;
const save=()=>{localStorage.setItem('dtb:saved',JSON.stringify(state.saved));updateCount()};
function updateCount(){$('#savedCount').textContent=state.saved.length}
const journey=[['La cabeza de todo','Génesis 1:1','¿Qué cambia cuando “principio” deja de ser solamente una fecha?',[1,2]],['Antes de la forma','Génesis 1:2','Entrá en tohu vavohu, tehom y ruach sin apurarte a llamar caos a todo.',[3,4,5]],['Cuando “bueno” no es moral','Génesis 1:4–31','Seguí las siete apariciones de tov como condición y funcionamiento.',[6,18]],['Un cielo forjado','Génesis 1:6–20','Recuperá la materialidad que “firmamento” volvió invisible.',[9,12,13]],['Animal y humano respiran igual','Génesis 1:20 · 2:7','Compará nephesh chayah antes de decidir qué hace único al humano.',[14,26]],['Humano de tierra','Génesis 2:5–15','Leé adam dentro de adamah: materia, tarea y pertenencia.',[22,24,29]],['La mitad que nunca fue costilla','Génesis 2:18–25','Revisá ezer kenegdo, tzela y la arquitectura de la paridad.',[30,31,32,33,34,35]]];
async function init(){state.data=await fetch('data/genesis.json').then(r=>r.json());bind();render();renderTerms();renderHome();renderJourney();updateCount();applyFont();showView('home')}
function bind(){
  $$('[data-chapter]').forEach(b=>{b.classList.toggle('active',+b.dataset.chapter===state.chapter);b.onclick=()=>{state.chapter=+b.dataset.chapter;localStorage.setItem('dtb:chapter',state.chapter);$$('[data-chapter]').forEach(x=>x.classList.toggle('active',x===b));render()}});
  $$('[data-layer]').forEach(b=>b.onclick=()=>{state.layer=b.dataset.layer;$$('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));render()});
  $$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
  $('#closeDialog').onclick=()=>$('#decodeDialog').close(); $('#searchBtn').onclick=()=>{$('#searchDialog').showModal();$('#searchInput').focus()};
  $('#searchInput').oninput=e=>search(e.target.value);
  $('#continueReading').onclick=()=>showView('reader');
  $('#fontDown').onclick=()=>setFont(-.1);$('#fontUp').onclick=()=>setFont(.1);$('#focusMode').onclick=()=>document.body.classList.toggle('focus');
  $('#savePersonalNote').onclick=savePersonalNote;$('#downloadNotebook').onclick=downloadNotebook;
}
function showView(v){$$('.view').forEach(x=>x.classList.remove('active'));$('#'+v+'View').classList.add('active');$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('#topContext').textContent={home:'Inicio',reader:'Génesis',journey:'Recorrido',dima:'DIMA',saved:'Cuaderno',about:'Créditos'}[v]||'';$('.chapter-switch').style.visibility=v==='reader'?'visible':'hidden';if(v==='saved')renderSaved();if(v==='home')renderHome();scrollTo({top:0,behavior:'smooth'})}
function render(){const ch=state.data.chapters[state.chapter];$('#chapterTitle').innerHTML=`Génesis <em>${state.chapter}</em>`;$('#verses').innerHTML=ch.map(v=>{let txt=state.layer==='hebrew'?(v.hebrew||'Texto hebreo en preparación'):notesIn(v.text);let key=`${state.chapter}:${v.number}`;return `<section class="verse ${state.layer==='hebrew'?'hebrew':''}" id="v-${key.replace(':','-')}"><span class="verse-num">${v.number}</span><p class="verse-text">${txt}<button class="bookmark ${state.saved.some(x=>x.type==='verse'&&x.key===key)?'saved':''}" data-save-verse="${key}" aria-label="Guardar">◇</button></p></section>`}).join('');
  $$('[data-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.note));$$('[data-save-verse]').forEach(b=>b.onclick=()=>toggleVerse(b.dataset.saveVerse,b));
  verseObserver?.disconnect();verseObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting&&!state.read.includes(e.target.id)){state.read.push(e.target.id);localStorage.setItem('dtb:read',JSON.stringify(state.read));renderHome()}}),{threshold:.65});$$('.verse').forEach(v=>verseObserver.observe(v));
}
function notesIn(t){return t.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,m=>{const n=+[...m].map(c=>SUP[c]).join('');return `<button class="note-ref" data-note="${n}" aria-label="Abrir nota ${n}">${n}</button>`})}
function openNote(n){const note=state.data.notes.find(x=>x.id===n);if(!note)return;if(!state.opened.includes(n)){state.opened.push(n);localStorage.setItem('dtb:opened',JSON.stringify(state.opened))}const saved=state.saved.some(x=>x.type==='note'&&x.key==n);$('#decodeContent').innerHTML=`<p class="decode-kicker">VERBUM REVELANS · ${String(n).padStart(2,'0')}</p><div class="decode-hebrew">${note.hebrew||''}</div><h2 class="decode-title">${note.title}</h2><div>${(note.evidence||[]).map(e=>`<span class="evidence ${e[0]==='D'?'d':''}">${e}</span>`).join('')}</div><h3 class="layer-label">CAMPO LINGÜÍSTICO + DECISIÓN DIMA</h3><p class="decode-body">${note.body}</p><p class="source-line">Fuente base: OSHB / WLC. Las etiquetas separan evidencia e interpretación.</p><div class="decode-actions"><button class="primary" id="saveNote">${saved?'Guardado':'Guardar lectura'}</button><button class="secondary" id="backVerse">Volver al versículo</button></div>`;$('#decodeDialog').showModal();$('#saveNote').onclick=()=>toggleNote(note);$('#backVerse').onclick=()=>$('#decodeDialog').close();renderHome()}
function toggleNote(note){const i=state.saved.findIndex(x=>x.type==='note'&&x.key==note.id);if(i>=0)state.saved.splice(i,1);else state.saved.push({type:'note',key:note.id,title:note.title,text:note.body});save();$('#decodeDialog').close()}
function toggleVerse(key,b){const i=state.saved.findIndex(x=>x.type==='verse'&&x.key===key);if(i>=0)state.saved.splice(i,1);else{const [c,n]=key.split(':');const v=state.data.chapters[c].find(x=>x.number===n);state.saved.push({type:'verse',key,title:`Génesis ${key}`,text:v.text.replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹]+/g,'')})}save();b.classList.toggle('saved')}
function renderTerms(){const featured=[1,3,5,6,9,14,16,22,28,30,32,35];$('#termGrid').innerHTML=featured.map(n=>{const x=state.data.notes.find(a=>a.id===n);return `<button class="term-card" data-card-note="${n}"><div class="hebrew">${x.hebrew||'—'}</div><h3>${x.title}</h3><p>${x.teaser||'Abrir campo lingüístico y decisión DIMA.'}</p></button>`}).join('');$$('[data-card-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.cardNote))}
function renderSaved(){const el=$('#savedList');el.innerHTML=state.saved.length?state.saved.slice().reverse().map((x,i)=>`<article class="saved-item"><strong>${x.type==='verse'?x.title:x.type==='personal'?'NOTA PERSONAL':'VERBUM REVELANS'}</strong><p>${x.type==='note'?x.title:x.text}</p><button class="remove-save" data-remove="${state.saved.length-1-i}" aria-label="Eliminar">×</button></article>`).join(''):'<article class="saved-item"><p>Todavía no guardaste ninguna marca. Tocá ◇ junto a un versículo o guardá una decodificación DIMA.</p></article>';$$('[data-remove]').forEach(b=>b.onclick=()=>{state.saved.splice(+b.dataset.remove,1);save();renderSaved();renderHome()})}
function renderHome(){if(!state.data)return;const day=(new Date().getDate()-1)%state.data.notes.length+1,n=state.data.notes.find(x=>x.id===day);$('#dailyCard').innerHTML=`<p class="eyebrow">PALABRA DEL DÍA</p><div class="daily-hebrew">${n.hebrew}</div><h2>${n.title}</h2><p>${n.teaser||'Una palabra, su campo y la decisión que abre.'}</p><button class="text-button" id="openDaily">Abrir decodificación →</button>`;$('#openDaily').onclick=()=>openNote(n.id);const done=state.steps.length;$('#progressPercent').textContent=Math.round(done/journey.length*100)+'%';$('#progressFill').style.width=(done/journey.length*100)+'%';$('#stepPreview').innerHTML=`<span>${String(Math.min(done+1,7)).padStart(2,'0')}</span><div><strong>${done===7?'Recorrido completo':journey[done][0]}</strong><small>${done===7?'Podés volver a atravesarlo desde otra palabra.':journey[done][2]}</small></div>`;$('#readStat').textContent=Math.min(state.read.length,53);$('#decodedStat').textContent=state.opened.length;$('#savedStat').textContent=state.saved.length}
function renderJourney(){$('#journeySteps').innerHTML=journey.map((s,i)=>`<article class="journey-step ${state.steps.includes(i)?'done':''}"><span>${String(i+1).padStart(2,'0')}</span><div><small>${s[1]}</small><h2>${s[0]}</h2><p>${s[2]}</p><div class="step-terms">${s[3].map(n=>{const x=state.data.notes.find(a=>a.id===n);return `<button data-card-note="${n}">${x?.hebrew||n}</button>`}).join('')}</div></div><button class="complete-step" data-step="${i}">${state.steps.includes(i)?'Atravesado ✓':'Marcar atravesado'}</button></article>`).join('');$$('[data-card-note]').forEach(b=>b.onclick=()=>openNote(+b.dataset.cardNote));$$('[data-step]').forEach(b=>b.onclick=()=>{const i=+b.dataset.step,p=state.steps.indexOf(i);p>=0?state.steps.splice(p,1):state.steps.push(i);localStorage.setItem('dtb:steps',JSON.stringify(state.steps));renderJourney();renderHome()})}
function savePersonalNote(){const t=$('#personalNote').value.trim();if(!t)return;state.saved.push({type:'personal',key:Date.now(),text:t});$('#personalNote').value='';save();renderSaved();renderHome()}
function downloadNotebook(){const lines=state.saved.map(x=>`## ${x.title||'Nota personal'}\n${x.text||x.title}`).join('\n\n');const blob=new Blob([`# Decoding the Bible · Mi cuaderno DIMA\n\n${lines}`],{type:'text/markdown'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mi-cuaderno-dima.md';a.click();URL.revokeObjectURL(a.href)}
function setFont(d){state.font=Math.max(.8,Math.min(1.4,state.font+d));localStorage.setItem('dtb:font',state.font);applyFont()}
function applyFont(){document.documentElement.style.setProperty('--reader-scale',state.font)}
function search(q){q=q.trim().toLowerCase();if(!q){$('#searchResults').innerHTML='';return}let out=[];for(const [c,vs] of Object.entries(state.data.chapters))for(const v of vs)if(v.text.toLowerCase().includes(q))out.push({c,v});$('#searchResults').innerHTML=out.slice(0,20).map(x=>`<button class="search-result" data-hit="${x.c}:${x.v.number}"><strong>Génesis ${x.c}:${x.v.number}</strong><br>${x.v.text}</button>`).join('')||'<p>Sin resultados.</p>';$$('[data-hit]').forEach(b=>b.onclick=()=>{const [c,n]=b.dataset.hit.split(':');state.chapter=+c;$$('[data-chapter]').forEach(x=>x.classList.toggle('active',+x.dataset.chapter===state.chapter));render();$('#searchDialog').close();showView('reader');setTimeout(()=>$('#v-'+c+'-'+n)?.scrollIntoView({behavior:'smooth',block:'center'}),80)})}
init().catch(e=>{console.error(e);$('#verses').innerHTML='<p>No se pudo cargar el texto.</p>'});
